 1 │ import "server-only";
 2 │ import { createServerClient } from "@supabase/ssr";
 3 │ import { cookies } from "next/headers";
 4 │ import { connection } from "next/server";
 5 │ import type { Database } from "./database.types";
 6 │ import { supabaseEnv } from "./env";
 7 │ 
 8 │ /**
 9 │  * Supabase client acting as the signed-in user (publishable key + session cookies).
10 │  * RLS is the security boundary; the app never uses the secret/service-role key.
11 │  * Create one per request.
12 │  */
13 │ export async function createClient() {
14 │   // Session reads and token checks use the current time, so always run them at request time
15 │   // (Cache Components would otherwise flag supabase-js's Date.now() during prerendering).
16 │   await connection();
17 │   const cookieStore = await cookies();
18 │   const { url, publishableKey } = supabaseEnv();
19 │ 
20 │   return createServerClient<Database>(url, publishableKey, {
21 │     cookies: {
22 │       getAll() {
23 │         return cookieStore.getAll();
24 │       },
25 │       setAll(cookiesToSet) {
26 │         try {
27 │           for (const { name, value, options } of cookiesToSet) cookieStore.set(name, value, options);
28 │         } catch {
29 │           // Server Components can't set cookies. The Proxy refreshes the session instead.
30 │         }
31 │       },
32 │     },
33 │   });
34 │ }
 1 │ export function supabaseEnv() {
 2 │   const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
 3 │   const publishableKey = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;
 4 │   if (!url || !publishableKey) {
 5 │     throw new Error(
 6 │       "Missing NEXT_PUBLIC_SUPABASE_URL or NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY. Copy .env.example to .env.local.",
 7 │     );
 8 │   }
 9 │   return { url, publishableKey };
10 │ }
 1 │ "use server";
 2 │ 
 3 │ import { revalidatePath } from "next/cache";
 4 │ import { requireUser } from "@/lib/auth";
 5 │ import { MAX_FILE_BYTES, runImport, type ImportResult } from "@/lib/csv/import";
 6 │ 
 7 │ export type ImportState = { result?: ImportResult; fileName?: string };
 8 │ 
 9 │ const CSV_TYPES = new Set(["", "text/csv", "text/plain", "application/csv", "application/vnd.ms-excel"]);
10 │ 
11 │ const fail = (error: string, fileName?: string): ImportState => ({ result: { ok: false, error }, fileName });
12 │ 
13 │ /** Validates the upload, then imports it as the signed-in user. Never throws to the client. */
14 │ export async function importCsv(_prev: ImportState, formData: FormData): Promise<ImportState> {
15 │   const { supabase } = await requireUser();
16 │ 
17 │   const file = formData.get("file");
18 │   if (!(file instanceof File) || file.name === "") return fail("Choose a CSV file to upload.");
19 │   const fileName = file.name;
20 │ 
21 │   if (file.size === 0) return fail("The file is empty.", fileName);
22 │   if (file.size > MAX_FILE_BYTES) return fail("The file is larger than 1 MB. Split it into smaller files.", fileName);
23 │   if (!fileName.toLowerCase().endsWith(".csv") || !CSV_TYPES.has(file.type)) {
24 │     return fail("Upload a .csv file.", fileName);
25 │   }
26 │ 
27 │   let text: string;
28 │   try {
29 │     text = new TextDecoder("utf-8", { fatal: true }).decode(await file.arrayBuffer());
30 │   } catch {
31 │     return fail("The file isn't valid UTF-8 text. Save it as “CSV UTF-8” and try again.", fileName);
32 │   }
33 │   if (text.includes("\u0000")) return fail("This doesn't look like a CSV text file.", fileName);
34 │ 
35 │   try {
36 │     const result = await runImport(supabase, text);
37 │     if (result.ok && result.imported > 0) revalidatePath("/tasks");
38 │     return { result, fileName };
39 │   } catch (error) {
40 │     console.error("import failed", error);
41 │     return fail("The import failed and no rows were saved. Please try again.", fileName);
42 │   }
43 │ }
 1 │ "use server";
