 3 │ import { redirect } from "next/navigation";
 4 │ import { createClient } from "@/lib/supabase/server";
 5 │ 
 6 │ export type AuthFormState = { error?: string; message?: string; email?: string };
 7 │ 
 8 │ export async function authenticate(_prev: AuthFormState, formData: FormData): Promise<AuthFormState> {
 9 │   const intent = formData.get("intent") === "signup" ? "signup" : "signin";
10 │   const email = String(formData.get("email") ?? "").trim();
11 │   const password = String(formData.get("password") ?? "");
12 │ 
13 │   if (!email || !password) return { error: "Enter your email and password.", email };
14 │ 
15 │   const supabase = await createClient();
16 │ 
17 │   if (intent === "signin") {
18 │     const { error } = await supabase.auth.signInWithPassword({ email, password });
19 │     if (error) return { error: "Incorrect email or password.", email };
20 │   } else {
21 │     if (password.length < 8) return { error: "Use a password of at least 8 characters.", email };
22 │     const { data, error } = await supabase.auth.signUp({ email, password });
23 │     if (error) return { error: error.message, email };
24 │     if (!data.session) return { message: "Check your email to confirm your account, then sign in.", email };
25 │   }
26 │ 
27 │   redirect("/tasks");
28 │ }
29 │ 
30 │ export async function signOut() {
31 │   const supabase = await createClient();
32 │   await supabase.auth.signOut();
33 │   redirect("/login");
34 │ }
 1 │ "use server";
 2 │ 
 3 │ import { revalidatePath } from "next/cache";
 4 │ import { requireUser } from "@/lib/auth";
 5 │ import { isTaskStatus, TASK_STATUSES, validateTaskInput } from "@/lib/tasks/validation";
 6 │ 
 7 │ export type TaskFormState = {
 8 │   errors?: string[];
 9 │   /** Submitted values, echoed back so the form keeps them after a failed save. */
10 │   values?: Record<string, string>;
11 │   /** Changes on every successful save so the form can reset. */
12 │   savedAt?: number;
13 │ };
14 │ 
15 │ export type TaskActionResult = { error?: string };
16 │ 
17 │ const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
18 │ const DUPLICATE_MESSAGE = "A task with this title and due date already exists.";
19 │ const GENERIC_MESSAGE = "Something went wrong saving the task. Please try again.";
20 │ 
21 │ function readForm(formData: FormData) {
22 │   const values = {
23 │     title: String(formData.get("title") ?? ""),
24 │     due_date: String(formData.get("due_date") ?? ""),
25 │     priority: String(formData.get("priority") ?? ""),
26 │     notes: String(formData.get("notes") ?? ""),
27 │     status: String(formData.get("status") ?? "todo"),
28 │   };
29 │   const result = validateTaskInput(values);
30 │   const errors = result.ok ? [] : [...result.errors];
31 │   if (!isTaskStatus(values.status)) errors.push(`status must be one of: ${TASK_STATUSES.join(", ")}`);
32 │   if (!result.ok || errors.length > 0) return { ok: false as const, errors, values };
33 │   return { ok: true as const, task: { ...result.value, status: values.status as (typeof TASK_STATUSES)[number] }, values };
34 │ }
35 │ 
36 │ function saveError(error: { code?: string; message: string }, values: Record<string, string>): TaskFormState {
37 │   if (error.code === "23505") return { errors: [DUPLICATE_MESSAGE], values };
38 │   console.error("task save failed", { code: error.code, message: error.message });
39 │   return { errors: [GENERIC_MESSAGE], values };
40 │ }
41 │ 
42 │ export async function createTask(_prev: TaskFormState, formData: FormData): Promise<TaskFormState> {
43 │   const { supabase } = await requireUser();
44 │   const form = readForm(formData);
45 │   if (!form.ok) return { errors: form.errors, values: form.values };
46 │ 
47 │   const { error } = await supabase.from("tasks").insert(form.task);
48 │   if (error) return saveError(error, form.values);
49 │ 
50 │   revalidatePath("/tasks");
51 │   return { savedAt: Date.now() };
52 │ }
53 │ 
54 │ export async function updateTask(id: string, _prev: TaskFormState, formData: FormData): Promise<TaskFormState> {
55 │   const { supabase } = await requireUser();
56 │   if (!UUID.test(id)) return { errors: ["Task not found."] };
57 │   const form = readForm(formData);
58 │   if (!form.ok) return { errors: form.errors, values: form.values };
59 │ 
60 │   const { data, error } = await supabase
61 │     .from("tasks")
62 │     .update(form.task)
63 │     .eq("id", id)
64 │     .is("deleted_at", null)
65 │     .select("id");
66 │   if (error) return saveError(error, form.values);
67 │   if (data.length === 0) return { errors: ["Task not found."], values: form.values };
68 │ 
69 │   revalidatePath("/tasks");
70 │   return { savedAt: Date.now() };
71 │ }
72 │ 
73 │ async function updateOne(id: string, patch: { status?: "todo" | "done"; deleted_at?: string }): Promise<TaskActionResult> {
74 │   const { supabase } = await requireUser();
75 │   if (!UUID.test(id)) return { error: "Task not found." };
76 │ 
77 │   const { data, error } = await supabase.from("tasks").update(patch).eq("id", id).is("deleted_at", null).select("id");
78 │   if (error) {
79 │     console.error("task update failed", { code: error.code, message: error.message });
80 │     return { error: GENERIC_MESSAGE };
81 │   }
82 │   if (data.length === 0) return { error: "Task not found." };
83 │ 
84 │   revalidatePath("/tasks");
85 │   return {};
86 │ }
87 │ 
88 │ export async function setCompleted(id: string, completed: boolean): Promise<TaskActionResult> {
89 │   return updateOne(id, { status: completed ? "done" : "todo" });
90 │ }
91 │ 
92 │ /** Soft delete: the row stays in the database with deleted_at set. */
93 │ export async function deleteTask(id: string): Promise<TaskActionResult> {
94 │   return updateOne(id, { deleted_at: new Date().toISOString() });
95 │ }
 1 │ import type { SupabaseClient } from "@supabase/supabase-js";
 2 │ import type { Database } from "@/lib/supabase/database.types";
 3 │ import { isTaskStatus, type TaskStatus } from "./validation";
 4 │ 
 5 │ export const LIST_LIMIT = 500;
 6 │ 
 7 │ export type Task = Pick<
 8 │   Database["public"]["Tables"]["tasks"]["Row"],
 9 │   "id" | "title" | "notes" | "due_date" | "priority" | "status"
10 │ >;
11 │ 
12 │ export type TaskFilters = { q: string; status: TaskStatus | null; priority: number | null };
13 │ 
14 │ type SearchParams = Record<string, string | string[] | undefined>;
15 │ 
16 │ const first = (value: string | string[] | undefined) => (Array.isArray(value) ? value[0] : value) ?? "";
17 │ 
18 │ /** Reads filters from URL search params, ignoring anything invalid. */
19 │ export function parseFilters(params: SearchParams): TaskFilters {
20 │   const q = first(params.q).trim().slice(0, 200);
21 │   const status = first(params.status);
22 │   const priority = first(params.priority);
23 │   return {
24 │     q,
25 │     status: isTaskStatus(status) ? status : null,
26 │     priority: /^[1-5]$/.test(priority) ? Number(priority) : null,
27 │   };
28 │ }
29 │ 
30 │ export const hasActiveFilters = (f: TaskFilters) => Boolean(f.q || f.status || f.priority);
31 │ 
32 │ /**
33 │  * Builds a PostgREST `or` filter for a case-insensitive substring match on title and notes.
34 │  * LIKE wildcards in the search text are escaped so they match literally, and the value is
35 │  * double-quoted so commas and parentheses can't break out of the filter syntax.
36 │  */
37 │ export function searchFilter(q: string): string {
38 │   const likeEscaped = q.replace(/[\\%_]/g, (c) => `\\${c}`);
39 │   const quoted = `"${`%${likeEscaped}%`.replace(/[\\"]/g, (c) => `\\${c}`)}"`;
40 │   return `title.ilike.${quoted},notes.ilike.${quoted}`;
41 │ }
42 │ 
43 │ type Client = SupabaseClient<Database>;
44 │ 
45 │ /** Live (not deleted) tasks for the signed-in user; RLS scopes rows to that user. */
46 │ export async function listTasks(supabase: Client, filters: TaskFilters): Promise<Task[]> {
47 │   let query = supabase
48 │     .from("tasks")
49 │     .select("id, title, notes, due_date, priority, status")
50 │     .is("deleted_at", null);
51 │ 
52 │   if (filters.status) query = query.eq("status", filters.status);
53 │   if (filters.priority) query = query.eq("priority", filters.priority);
54 │   if (filters.q) query = query.or(searchFilter(filters.q));
55 │ 
56 │   const { data, error } = await query
57 │     .order("due_date", { ascending: true })
58 │     .order("priority", { ascending: true })
59 │     .order("created_at", { ascending: true })
60 │     .limit(LIST_LIMIT);
61 │ 
62 │   if (error) throw new Error(`Could not load tasks: ${error.message}`);
63 │   return data;
64 │ }
65 │ 
66 │ export async function countLiveTasks(supabase: Client): Promise<number> {
67 │   const { count, error } = await supabase
68 │     .from("tasks")
69 │     .select("id", { count: "exact", head: true })
70 │     .is("deleted_at", null);
71 │   if (error) throw new Error(`Could not count tasks: ${error.message}`);
72 │   return count ?? 0;
73 │ }

