18 │ /** Reads filters from URL search params, ignoring anything invalid. */
19 │ export function parseFilters(params: SearchParams): TaskFilters {
20 │   const q = first(params.q).trim().slice(0, 200);
21 │   const status = first(params.status);
22 │   const priority = first(params.priority);
23 │   return {
