32 │ /**
33 │  * Builds a PostgREST `or` filter for a case-insensitive substring match on title and notes.
34 │  * LIKE wildcards in the search text are escaped so they match literally, and the value is
35 │  * double-quoted so commas and parentheses can't break out of the filter syntax.
36 │  */
37 │ export function searchFilter(q: string): string {
38 │   const likeEscaped = q.replace(/[\\%_]/g, (c) => `\\${c}`);
39 │   const quoted = `"${`%${likeEscaped}%`.replace(/[\\"]/g, (c) => `\\${c}`)}"`;
40 │   return `title.ilike.${quoted},notes.ilike.${quoted}`;
41 │ }
