 1 │ /**
 2 │  * Duplicate key: title trimmed and lower-cased, plus due date.
 3 │  * Mirrors the database's unique index on (user_id, lower(title), due_date).
 4 │  */
 5 │ export function dedupeKey(title: string, dueDate: string): string {
 6 │   return `${title.trim().toLowerCase()}\u0000${dueDate}`;
 7 │ }
