 9 │ type Dedupable = { rowNumber: number; task: { title: string; due_date: string } };
10 │ 
11 │ /** Splits rows into first occurrences and later copies (each pointing at the first). */
12 │ export function findInFileDuplicates<T extends Dedupable>(items: T[]) {
13 │   const firstRowByKey = new Map<string, number>();
14 │   const unique: T[] = [];
15 │   const duplicates: { item: T; firstRowNumber: number }[] = [];
16 │ 
17 │   for (const item of items) {
18 │     const key = dedupeKey(item.task.title, item.task.due_date);
19 │     const firstRowNumber = firstRowByKey.get(key);
20 │     if (firstRowNumber === undefined) {
21 │       firstRowByKey.set(key, item.rowNumber);
22 │       unique.push(item);
23 │     } else {
24 │       duplicates.push({ item, firstRowNumber });
25 │     }
26 │   }
27 │ 
28 │   return { unique, duplicates };
29 │ }
