 22 │ export type ImportResult =
 23 │   | {
 24 │       ok: true;
 25 │       imported: number;
 26 │       blankSkipped: number;
 27 │       headers: string[];
 28 │       rejected: RejectedRow[];
 29 │     }
 30 │   | { ok: false; error: string };
