 1 │ // Single source of truth for task field rules, shared by the task form and CSV import (R6).
 2 │ 
 3 │ export const TITLE_MAX_LENGTH = 200;
 4 │ export const TASK_STATUSES = ["todo", "in_progress", "done"] as const;
 5 │ export type TaskStatus = (typeof TASK_STATUSES)[number];
 6 │ 
 7 │ export const STATUS_LABELS: Record<TaskStatus, string> = {
 8 │   todo: "To do",
 9 │   in_progress: "In progress",
10 │   done: "Done",
11 │ };
12 │ 
13 │ export type TaskInput = {
14 │   title: string;
15 │   due_date: string;
16 │   priority: number;
17 │   notes: string | null;
18 │ };
19 │ 
20 │ export type RawTaskInput = {
21 │   title?: unknown;
22 │   due_date?: unknown;
23 │   priority?: unknown;
24 │   notes?: unknown;
25 │ };
26 │ 
27 │ export type ValidationResult =
28 │   | { ok: true; value: TaskInput }
29 │   | { ok: false; errors: string[] };
30 │ 
31 │ export const MESSAGES = {
32 │   titleRequired: "title is required",
33 │   titleTooLong: `title must be ${TITLE_MAX_LENGTH} characters or fewer`,
34 │   dueDateRequired: "due_date is required",
35 │   dueDateInvalid: "due_date must be a real date in YYYY-MM-DD format",
36 │   priorityRequired: "priority is required",
37 │   priorityInvalid: "priority must be a whole number from 1 to 5",
38 │ } as const;
39 │ 
40 │ const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
41 │ const PRIORITY_PATTERN = /^[1-5]$/;
42 │ 
43 │ function asTrimmedString(value: unknown): string {
44 │   if (value === null || value === undefined) return "";
45 │   return String(value).trim();
46 │ }
47 │ 
48 │ /** True when `value` is YYYY-MM-DD and names a day that exists on the calendar. */
49 │ export function isValidIsoDate(value: string): boolean {
50 │   const match = DATE_PATTERN.exec(value);
51 │   if (!match) return false;
52 │   const [year, month, day] = match.slice(1).map(Number);
53 │   // Year 0 doesn't exist in Postgres's (proleptic Gregorian, AD) date type.
54 │   if (year < 1) return false;
55 │   const date = new Date(0);
56 │   // setUTCFullYear avoids Date.UTC's 0–99 → 1900–1999 mapping.
57 │   date.setUTCFullYear(year, month - 1, day);
58 │   return (
59 │     date.getUTCFullYear() === year &&
60 │     date.getUTCMonth() === month - 1 &&
61 │     date.getUTCDate() === day
62 │   );
63 │ }
64 │ 
65 │ /** Validates every field and returns all failure reasons, not just the first. */
66 │ export function validateTaskInput(raw: RawTaskInput): ValidationResult {
67 │   const errors: string[] = [];
68 │ 
69 │   const title = asTrimmedString(raw.title);
70 │   if (title === "") errors.push(MESSAGES.titleRequired);
71 │   else if ([...title].length > TITLE_MAX_LENGTH) errors.push(MESSAGES.titleTooLong);
72 │ 
73 │   const dueDate = asTrimmedString(raw.due_date);
74 │   if (dueDate === "") errors.push(MESSAGES.dueDateRequired);
75 │   else if (!isValidIsoDate(dueDate)) errors.push(MESSAGES.dueDateInvalid);
76 │ 
77 │   const priorityText = asTrimmedString(raw.priority);
78 │   if (priorityText === "") errors.push(MESSAGES.priorityRequired);
79 │   else if (!PRIORITY_PATTERN.test(priorityText)) errors.push(MESSAGES.priorityInvalid);
80 │ 
81 │   if (errors.length > 0) return { ok: false, errors };
82 │ 
83 │   const notes = asTrimmedString(raw.notes);
84 │   return {
85 │     ok: true,
86 │     value: {
87 │       title,
88 │       due_date: dueDate,
89 │       priority: Number(priorityText),
90 │       notes: notes === "" ? null : notes,
91 │     },
92 │   };
93 │ }
94 │ 
95 │ export function isTaskStatus(value: unknown): value is TaskStatus {
96 │   return typeof value === "string" && (TASK_STATUSES as readonly string[]).includes(value);
97 │ }
